class MountainSpursTest{public static void main(String[]args){double increased=0;int raised=0;for(int z=-100;z<=100;z++)for(int x=-100;x<=100;x++){double u=x/100.,v=z/100.;double a=OrganicMountainRanges.profile(u*.28,v*.14,.14,2,.5,71,0),b=OrganicMountainRanges.profile(u*.28,v*.14,.14,2,.5,71,1);if(b+1e-10<a||!Double.isFinite(b))throw new AssertionError("Invalid spur profile");if(Math.abs(v)>.2&&b-a>.03){raised++;increased+=b-a;}}if(raised<100||increased<10)throw new AssertionError("Spurs not pronounced");if(OrganicMountainRanges.profile(0,.25,.14,2,.5,71,1)!=0)throw new AssertionError("Spurs extend past smooth envelope");System.out.println("PASS: stronger branching ridges with tapered outer foothills; raised samples="+raised);}}
